    rdfs:domain <https://w3id.org/ontojourney/core#Protagonist> ;
    rdfs:range <https://w3id.org/ontojourney/core#HeroicNarrativeJourneyExecution> ;
    rdfs:subPropertyOf <http://purl.org/nemo/gufo#participatedIn> .

<https://w3id.org/ontojourney/core#prescribesTransformation> a owl:ObjectProperty ;
