<https://w3id.org/ontojourney/core#ConditionDescription> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "ConditionDescription"@en ;
    rdfs:comment "A Normative Description that specifies a condition against which a situation can be assessed."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NormativeDescription> .

<https://w3id.org/ontojourney/core#EducationalPurpose> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "EducationalPurpose"@en ;
    rdfs:comment "A Goal Description that states an educational aim of a Learning Journey Model."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#GoalDescription> .

<https://w3id.org/ontojourney/core#HeroicNarrativeJourneyModel> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "HeroicNarrativeJourneyModel"@en ;
    rdfs:comment "A Narrative Journey Model that frames a meaningful progression through demanding stages towards transformation and closure as a heroic trajectory."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NarrativeJourneyModel> .

<https://w3id.org/ontojourney/core#HeroicNarrativeLearningJourneyExecution> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "HeroicNarrativeLearningJourneyExecution"@en ;
    rdfs:comment "A Heroic Narrative Journey Execution and Learning Journey Execution of one Heroic Narrative Learning Journey Model, with exactly one focal Person participating as both Protagonist and Learner."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#HeroicNarrativeJourneyExecution>,
        <https://w3id.org/ontojourney/core#LearningJourneyExecution> .

<https://w3id.org/ontojourney/core#JourneyNarrative> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "JourneyNarrative"@en ;
    rdfs:comment "Narrative Content that organises the narrative progression of a Narrative Journey Model as a whole."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NarrativeContent> .

<https://w3id.org/ontojourney/core#Learner> a <http://purl.org/nemo/gufo#Role>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "Learner"@en ;
    rdfs:comment "A historical role instantiated by a Person through participation in a Learning Journey Execution."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#Person> .

<https://w3id.org/ontojourney/core#MissionSpecification> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "MissionSpecification"@en ;
    rdfs:comment "A Normative Description that states what the Learner is invited or expected to pursue within an HLJ stage and may combine a desired result with directions for action."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NormativeDescription> .

<https://w3id.org/ontojourney/core#NarrativeFraming> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "NarrativeFraming"@en ;
    rdfs:comment "Narrative Content that gives one HLJ Stage Specification its local narrative context and connects it to the wider journey."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NarrativeContent> .

<https://w3id.org/ontojourney/core#NarrativeJourneyExecution> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "NarrativeJourneyExecution"@en ;
    rdfs:comment "A Journey Execution of a Narrative Journey Model in which the performed stages enact a narratively organised journey."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#JourneyExecution> .

<https://w3id.org/ontojourney/core#Protagonist> a <http://purl.org/nemo/gufo#Role>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "Protagonist"@en ;
    rdfs:comment "A historical role instantiated by a Person through participation as the focal subject of a Heroic Narrative Journey Execution."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#Person> .

<https://w3id.org/ontojourney/core#AssistanceProvision> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "AssistanceProvision"@en ;
    rdfs:comment "An event within an HLJ Stage Execution in which assistance specified for that stage is provided."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#Event> .

<https://w3id.org/ontojourney/core#AssistanceSpecification> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "AssistanceSpecification"@en ;
    rdfs:comment "A Normative Description of support intended to be made available within an HLJ Stage Specification."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NormativeDescription> .

<https://w3id.org/ontojourney/core#ChallengeEncounter> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "ChallengeEncounter"@en ;
    rdfs:comment "An event within an HLJ Stage Execution in which the specified challenge of that stage is faced, whether or not it is successfully addressed."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#Event> .

<https://w3id.org/ontojourney/core#ChallengePerformance> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "ChallengePerformance"@en ;
    rdfs:comment "An event within an HLJ Stage Execution in which action is directed towards the specified challenge of that stage; its occurrence does not by itself imply success."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#Event> .

<https://w3id.org/ontojourney/core#ClosureSituation> a <http://purl.org/nemo/gufo#SituationType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "ClosureSituation"@en ;
    rdfs:comment "A situation brought about by a Journey Execution that satisfies a Closure Specification; in a successful execution, that specification is defined by the executed model."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#Situation> .

<https://w3id.org/ontojourney/core#ClosureSpecification> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "ClosureSpecification"@en ;
    rdfs:comment "A Condition Description defined by a Journey Model that states the condition under which an execution of the model counts as having reached closure."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#ConditionDescription> .

<https://w3id.org/ontojourney/core#GoalDescription> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "GoalDescription"@en ;
    rdfs:comment "A Normative Description whose propositional content describes a situation intended to be attained."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NormativeDescription> .

<https://w3id.org/ontojourney/core#HeroicNarrativeJourneyExecution> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "HeroicNarrativeJourneyExecution"@en ;
    rdfs:comment "A Narrative Journey Execution of a Heroic Narrative Journey Model that constitutes one focal heroic trajectory with exactly one Protagonist."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NarrativeJourneyExecution> .

<https://w3id.org/ontojourney/core#InformationObject> a <http://purl.org/nemo/gufo#Kind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "InformationObject"@en ;
    rdfs:comment "An entity whose identity is determined by its informational content and that may be expressed through different physical or digital carriers."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#FunctionalComplex> .

<https://w3id.org/ontojourney/core#LearningJourneyExecution> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "LearningJourneyExecution"@en ;
    rdfs:comment "A Journey Execution of a Learning Journey Model in which at least one Person participates as Learner."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#JourneyExecution> .

<https://w3id.org/ontojourney/core#LearningJourneyModel> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "LearningJourneyModel"@en ;
    rdfs:comment "A Journey Model and Plan Description that intentionally organises an educational experience and has at least one Educational Purpose."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#JourneyModel>,
        <https://w3id.org/ontojourney/core#PlanDescription> .

<https://w3id.org/ontojourney/core#NarrativeContent> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "NarrativeContent"@en ;
    rdfs:comment "An Information Object that organises characters, events, or themes as narrative content, independently of the medium through which it is expressed."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#InformationObject> .

<https://w3id.org/ontojourney/core#NarrativeJourneyModel> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "NarrativeJourneyModel"@en ;
    rdfs:comment "A Journey Model whose overall progression is organised by exactly one Journey Narrative."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#JourneyModel> .

<https://w3id.org/ontojourney/core#PlanDescription> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "PlanDescription"@en ;
    rdfs:comment "A Normative Description that prescribes or organises intended actions and events towards a purpose."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NormativeDescription> .

<https://w3id.org/ontojourney/core#TransformationEvent> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "TransformationEvent"@en ;
    rdfs:comment "An event within a Journey Execution that brings about one Realized Transformation."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#Event> .

<https://w3id.org/ontojourney/core#ChallengeSpecification> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "ChallengeSpecification"@en ;
    rdfs:comment "A Normative Description assigned to a Stage Specification that describes a demand, obstacle, problem, task, or condition that makes progression demanding."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NormativeDescription> .

<https://w3id.org/ontojourney/core#Description> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "Description"@en ;
    rdfs:comment "An Information Object that expresses a conceptualization of entities or configurations and provides criteria for interpreting or assessing them."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#InformationObject> .

<https://w3id.org/ontojourney/core#HLJStageExecution> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "HLJStageExecution"@en ;
    rdfs:comment "A Stage Execution of an HLJ Stage Specification that may include Challenge Encounters, Challenge Performances, and Assistance Provisions connected to specifications of that same stage."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#StageExecution> .

<https://w3id.org/ontojourney/core#HLJStageSpecification> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "HLJStageSpecification"@en ;
    rdfs:comment "A Stage Specification and Plan Description in the Heroine's Learning Journey anatomy that contains exactly one Narrative Framing, Mission Specification, Challenge Specification, and Assistance Specification."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#PlanDescription>,
        <https://w3id.org/ontojourney/core#StageSpecification> .

<https://w3id.org/ontojourney/core#IntendedTransformation> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "IntendedTransformation"@en ;
    rdfs:comment "A Goal Description prescribed by a Journey Model that specifies a transformation the model is intended to bring about."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#GoalDescription> .

<https://w3id.org/ontojourney/core#Person> a <http://purl.org/nemo/gufo#Kind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "Person"@en ;
    rdfs:comment "A human individual who may participate in Journey Executions and whose identity is preserved across the historical roles Protagonist and Learner."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#FunctionalComplex> .

<https://w3id.org/ontojourney/core#RealizedTransformation> a <http://purl.org/nemo/gufo#SituationType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "RealizedTransformation"@en ;
    rdfs:comment "A situation brought about by one or more Transformation Events that represents an actual change concerning exactly one Person and satisfies one Intended Transformation."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#Situation> .

<https://w3id.org/ontojourney/core#StageExecution> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "StageExecution"@en ;
    rdfs:comment "An event within a Journey Execution that enacts one Stage Specification belonging to the executed Journey Model."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#Event> .

<https://w3id.org/ontojourney/core#JourneyExecution> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "JourneyExecution"@en ;
    rdfs:comment "A complex event in which one Journey Model is enacted in a particular context through one or more Stage Executions."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#Event> .

<https://w3id.org/ontojourney/core#JourneyModel> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "JourneyModel"@en ;
    rdfs:comment "A Description that characterises a reusable journey pattern through one or more Stage Specifications and one Closure Specification, and may prescribe Intended Transformations."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#Description> .

<https://w3id.org/ontojourney/core#NormativeDescription> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "NormativeDescription"@en ;
    rdfs:comment "A Description that prescribes, permits, or evaluates possible actions or situations instead of merely characterising them."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#Description> .

<https://w3id.org/ontojourney/core#StageSpecification> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "StageSpecification"@en ;
    rdfs:comment "A Description that characterises a model-specific stage of a Journey Model, whether as a descriptive pattern or as a prescribed part of a plan, and may be linked to other Stage Specifications through directlyPrecedesStage."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#Description> .

PREFIX oj: <https://w3id.org/ontojourney/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?model ?execution WHERE { ?model a/rdfs:subClassOf* oj:JourneyModel . OPTIONAL { ?execution a/rdfs:subClassOf* oj:JourneyExecution ; oj:isExecutionOfJourneyModel ?model } }

PREFIX oj: <https://w3id.org/ontojourney/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?model WHERE { ?model a/rdfs:subClassOf* oj:HeroicNarrativeLearningJourneyModel ; oj:hasNarrative ?n ; oj:hasEducationalPurpose ?p ; oj:prescribesTransformation ?t ; oj:definesClosure ?c ; oj:hasStage ?s1, ?s2 . ?n a/rdfs:subClassOf* oj:JourneyNarrative . ?p a/rdfs:subClassOf* oj:EducationalPurpose . ?t a/rdfs:subClassOf* oj:IntendedLearningTransformation . ?c a/rdfs:subClassOf* oj:ClosureSpecification . ?s1 a/rdfs:subClassOf* oj:StageSpecification ; oj:directlyPrecedesStage ?s2 . ?s2 a/rdfs:subClassOf* oj:StageSpecification . FILTER(?s1 != ?s2) FILTER EXISTS { ?model oj:hasStage/oj:hasChallenge ?ch . ?ch a/rdfs:subClassOf* oj:ChallengeSpecification } }

PREFIX oj: <https://w3id.org/ontojourney/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?model ?stage ?next WHERE { ?model a/rdfs:subClassOf* oj:JourneyModel ; oj:hasStage ?stage . OPTIONAL { ?stage oj:directlyPrecedesStage ?next . ?model oj:hasStage ?next } }

PREFIX oj: <https://w3id.org/ontojourney/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?execution ?model ?stageExecution ?stage WHERE { ?execution a/rdfs:subClassOf* oj:JourneyExecution ; oj:isExecutionOfJourneyModel ?model ; oj:hasStageExecution ?stageExecution . ?stageExecution oj:isExecutionOfStageSpecification ?stage . ?model oj:hasStage ?stage }

PREFIX oj: <https://w3id.org/ontojourney/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?execution ?person ?alsoLearner WHERE { ?execution a/rdfs:subClassOf* oj:HeroicNarrativeJourneyExecution . ?person a/rdfs:subClassOf* oj:Person ; oj:participatesAsProtagonistIn ?execution . BIND(EXISTS {?person oj:participatesAsLearnerIn ?execution } AS ?alsoLearner) }

PREFIX oj: <https://w3id.org/ontojourney/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?model ?intended ?execution ?realized ?person WHERE { ?model oj:prescribesTransformation ?intended . OPTIONAL { ?execution oj:isExecutionOfJourneyModel ?model ; oj:hasTransformationEvent/oj:producesTransformation ?realized . ?realized oj:satisfiesIntendedTransformation ?intended ; oj:isTransformationOf ?person . ?person oj:participatesAsProtagonistIn ?execution ; oj:participatesAsLearnerIn ?execution } }

PREFIX oj: <https://w3id.org/ontojourney/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?execution ?model ?person WHERE { ?execution a/rdfs:subClassOf* oj:SuccessfulHeroicNarrativeLearningJourneyExecution ; oj:isExecutionOfJourneyModel ?model ; oj:producesClosure/oj:satisfiesClosureSpecification ?closure ; oj:hasTransformationEvent/oj:producesTransformation ?realized . ?model oj:definesClosure ?closure ; oj:prescribesTransformation ?intended . ?intended a/rdfs:subClassOf* oj:IntendedLearningTransformation . ?realized oj:satisfiesIntendedTransformation ?intended ; oj:isTransformationOf ?person . ?person oj:participatesAsProtagonistIn ?execution ; oj:participatesAsLearnerIn ?execution }

PREFIX oj: <https://w3id.org/ontojourney/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?stage ?framing ?challenge ?assistance ?mission WHERE { ?stage a/rdfs:subClassOf* oj:HLJStageSpecification . OPTIONAL { ?stage oj:hasNarrativeFraming ?framing } OPTIONAL { ?stage oj:hasChallenge ?challenge } OPTIONAL { ?stage oj:hasAssistance ?assistance } OPTIONAL { ?stage oj:hasMission ?mission } }

PREFIX oj: <https://w3id.org/ontojourney/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?stageExecution ?event ?specification ?relation WHERE { ?stageExecution a/rdfs:subClassOf* oj:HLJStageExecution ; oj:isExecutionOfStageSpecification ?stage . VALUES (?has ?relation ?specified) { (oj:hasChallengeEncounter oj:isEncounterOf oj:hasChallenge) (oj:hasChallengePerformance oj:addressesChallenge oj:hasChallenge) (oj:hasAssistanceProvision oj:realizesAssistance oj:hasAssistance) } ?stageExecution ?has ?event . ?event ?relation ?specification . ?stage ?specified ?specification }

@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix vann: <http://purl.org/vocab/vann/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<https://w3id.org/ontojourney/core> a owl:Ontology ;
    dcterms:creator "Luis Felipe Coimbra Costa" ;
    dcterms:description "A reference ontology for narrative-heroic learning journeys, modeled in OntoUML and grounded in UFO."@en ;
    dcterms:identifier "10.5281/zenodo.24420185" ;
    dcterms:issued "2026-11-21"^^xsd:date ;
    dcterms:license <https://creativecommons.org/licenses/by/4.0/> ;
    dcterms:modified "2026-11-21"^^xsd:date ;
    dcterms:title "OntoJourney Core"@en ;
    vann:preferredNamespacePrefix "oj" ;
    vann:preferredNamespaceUri "https://w3id.org/ontojourney/core#" ;
    owl:imports <http://purl.org/nemo/gufo#> ;
    owl:priorVersion <https://w3id.org/ontojourney/core/0.9.1> ;
    owl:versionIRI <https://w3id.org/ontojourney/core/0.9.2> ;
    owl:versionInfo "0.9.2" .

<https://w3id.org/ontojourney/core#HeroicNarrativeLearningJourneyModel> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "HeroicNarrativeLearningJourneyModel"@en ;
    rdfs:comment "A Heroic Narrative Journey Model and Learning Journey Model whose identity includes one Journey Narrative, at least two connected Stage Specifications, at least one challenged stage, at least one Educational Purpose, at least one Intended Learning Transformation, and one Closure Specification."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#HeroicNarrativeJourneyModel>,
        <https://w3id.org/ontojourney/core#LearningJourneyModel> .

<https://w3id.org/ontojourney/core#IntendedLearningTransformation> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "IntendedLearningTransformation"@en ;
    rdfs:comment "An Intended Transformation that specifies a learning-related change to be pursued through a learning journey."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#IntendedTransformation> .

<https://w3id.org/ontojourney/core#SuccessfulHeroicNarrativeLearningJourneyExecution> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "SuccessfulHeroicNarrativeLearningJourneyExecution"@en ;
    rdfs:comment "A Heroic Narrative Learning Journey Execution that produces a Closure Situation satisfying the executed model's Closure Specification and at least one Realized Transformation of the focal Person satisfying an Intended Learning Transformation prescribed by that model."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#HeroicNarrativeLearningJourneyExecution> .

<https://w3id.org/ontojourney/core#addressesChallenge> a owl:ObjectProperty ;
    rdfs:label "addressesChallenge"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#ChallengePerformance> ;
    rdfs:range <https://w3id.org/ontojourney/core#ChallengeSpecification> .

<https://w3id.org/ontojourney/core#definesClosure> a owl:ObjectProperty ;
    rdfs:label "definesClosure"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#JourneyModel> ;
    rdfs:range <https://w3id.org/ontojourney/core#ClosureSpecification> .

<https://w3id.org/ontojourney/core#directlyPrecedesStage> a owl:ObjectProperty ;
    rdfs:label "directlyPrecedesStage"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#StageSpecification> ;
    rdfs:range <https://w3id.org/ontojourney/core#StageSpecification> .

<https://w3id.org/ontojourney/core#hasAssistance> a owl:ObjectProperty ;
    rdfs:label "hasAssistance"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#HLJStageSpecification> ;
    rdfs:range <https://w3id.org/ontojourney/core#AssistanceSpecification> .

<https://w3id.org/ontojourney/core#hasAssistanceProvision> a owl:ObjectProperty ;
    rdfs:label "hasAssistanceProvision"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#HLJStageExecution> ;
    rdfs:range <https://w3id.org/ontojourney/core#AssistanceProvision> .

<https://w3id.org/ontojourney/core#hasChallenge> a owl:ObjectProperty ;
    rdfs:label "hasChallenge"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#StageSpecification> ;
    rdfs:range <https://w3id.org/ontojourney/core#ChallengeSpecification> .

<https://w3id.org/ontojourney/core#hasChallengeEncounter> a owl:ObjectProperty ;
    rdfs:label "hasChallengeEncounter"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#HLJStageExecution> ;
    rdfs:range <https://w3id.org/ontojourney/core#ChallengeEncounter> .

<https://w3id.org/ontojourney/core#hasChallengePerformance> a owl:ObjectProperty ;
    rdfs:label "hasChallengePerformance"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#HLJStageExecution> ;
    rdfs:range <https://w3id.org/ontojourney/core#ChallengePerformance> .

<https://w3id.org/ontojourney/core#hasEducationalPurpose> a owl:ObjectProperty ;
    rdfs:label "hasEducationalPurpose"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#LearningJourneyModel> ;
    rdfs:range <https://w3id.org/ontojourney/core#EducationalPurpose> .

<https://w3id.org/ontojourney/core#hasMission> a owl:ObjectProperty ;
    rdfs:label "hasMission"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#HLJStageSpecification> ;
    rdfs:range <https://w3id.org/ontojourney/core#MissionSpecification> .

<https://w3id.org/ontojourney/core#hasNarrative> a owl:ObjectProperty ;
    rdfs:label "hasNarrative"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#NarrativeJourneyModel> ;
    rdfs:range <https://w3id.org/ontojourney/core#JourneyNarrative> .

<https://w3id.org/ontojourney/core#hasNarrativeFraming> a owl:ObjectProperty ;
    rdfs:label "hasNarrativeFraming"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#HLJStageSpecification> ;
    rdfs:range <https://w3id.org/ontojourney/core#NarrativeFraming> .

<https://w3id.org/ontojourney/core#hasStage> a owl:ObjectProperty ;
    rdfs:label "hasStage"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#JourneyModel> ;
    rdfs:range <https://w3id.org/ontojourney/core#StageSpecification> .

<https://w3id.org/ontojourney/core#hasStageExecution> a owl:ObjectProperty ;
    rdfs:label "hasStageExecution"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#JourneyExecution> ;
    rdfs:range <https://w3id.org/ontojourney/core#StageExecution> .

<https://w3id.org/ontojourney/core#hasTransformationEvent> a owl:ObjectProperty ;
    rdfs:label "hasTransformationEvent"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#JourneyExecution> ;
    rdfs:range <https://w3id.org/ontojourney/core#TransformationEvent> .

<https://w3id.org/ontojourney/core#isEncounterOf> a owl:ObjectProperty ;
    rdfs:label "isEncounterOf"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#ChallengeEncounter> ;
    rdfs:range <https://w3id.org/ontojourney/core#ChallengeSpecification> .

<https://w3id.org/ontojourney/core#isExecutionOfJourneyModel> a owl:ObjectProperty ;
    rdfs:label "isExecutionOfJourneyModel"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#JourneyExecution> ;
    rdfs:range <https://w3id.org/ontojourney/core#JourneyModel> .

<https://w3id.org/ontojourney/core#isExecutionOfStageSpecification> a owl:ObjectProperty ;
    rdfs:label "isExecutionOfStageSpecification"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#StageExecution> ;
    rdfs:range <https://w3id.org/ontojourney/core#StageSpecification> .

<https://w3id.org/ontojourney/core#isTransformationOf> a owl:ObjectProperty ;
    rdfs:label "isTransformationOf"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#RealizedTransformation> ;
    rdfs:range <https://w3id.org/ontojourney/core#Person> .

<https://w3id.org/ontojourney/core#participatesAsLearnerIn> a owl:ObjectProperty ;
    rdfs:label "participatesAsLearnerIn"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#Learner> ;
    rdfs:range <https://w3id.org/ontojourney/core#LearningJourneyExecution> ;
    rdfs:subPropertyOf <http://purl.org/nemo/gufo#participatedIn> .

<https://w3id.org/ontojourney/core#participatesAsProtagonistIn> a owl:ObjectProperty ;
    rdfs:label "participatesAsProtagonistIn"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#Protagonist> ;
    rdfs:range <https://w3id.org/ontojourney/core#HeroicNarrativeJourneyExecution> ;
    rdfs:subPropertyOf <http://purl.org/nemo/gufo#participatedIn> .

<https://w3id.org/ontojourney/core#prescribesTransformation> a owl:ObjectProperty ;
    rdfs:label "prescribesTransformation"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#JourneyModel> ;
    rdfs:range <https://w3id.org/ontojourney/core#IntendedTransformation> .

<https://w3id.org/ontojourney/core#producesClosure> a owl:ObjectProperty ;
    rdfs:label "producesClosure"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#JourneyExecution> ;
    rdfs:range <https://w3id.org/ontojourney/core#ClosureSituation> ;
    rdfs:subPropertyOf <http://purl.org/nemo/gufo#broughtAbout> .

<https://w3id.org/ontojourney/core#producesTransformation> a owl:ObjectProperty ;
    rdfs:label "producesTransformation"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#TransformationEvent> ;
    rdfs:range <https://w3id.org/ontojourney/core#RealizedTransformation> ;
    rdfs:subPropertyOf <http://purl.org/nemo/gufo#broughtAbout> .

<https://w3id.org/ontojourney/core#realizesAssistance> a owl:ObjectProperty ;
    rdfs:label "realizesAssistance"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#AssistanceProvision> ;
    rdfs:range <https://w3id.org/ontojourney/core#AssistanceSpecification> .

<https://w3id.org/ontojourney/core#satisfiesClosureSpecification> a owl:ObjectProperty ;
    rdfs:label "satisfiesClosureSpecification"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#ClosureSituation> ;
    rdfs:range <https://w3id.org/ontojourney/core#ClosureSpecification> .

<https://w3id.org/ontojourney/core#satisfiesIntendedTransformation> a owl:ObjectProperty ;
    rdfs:label "satisfiesIntendedTransformation"@en ;
    rdfs:domain <https://w3id.org/ontojourney/core#RealizedTransformation> ;
    rdfs:range <https://w3id.org/ontojourney/core#IntendedTransformation> .

<https://w3id.org/ontojourney/core#ConditionDescription> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "ConditionDescription"@en ;
    rdfs:comment "A Normative Description that specifies a condition against which a situation can be assessed."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NormativeDescription> .

<https://w3id.org/ontojourney/core#EducationalPurpose> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "EducationalPurpose"@en ;
    rdfs:comment "A Goal Description that states an educational aim of a Learning Journey Model."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#GoalDescription> .

<https://w3id.org/ontojourney/core#HeroicNarrativeJourneyModel> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "HeroicNarrativeJourneyModel"@en ;
    rdfs:comment "A Narrative Journey Model that frames a meaningful progression through demanding stages towards transformation and closure as a heroic trajectory."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NarrativeJourneyModel> .

<https://w3id.org/ontojourney/core#HeroicNarrativeLearningJourneyExecution> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "HeroicNarrativeLearningJourneyExecution"@en ;
    rdfs:comment "A Heroic Narrative Journey Execution and Learning Journey Execution of one Heroic Narrative Learning Journey Model, with exactly one focal Person participating as both Protagonist and Learner."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#HeroicNarrativeJourneyExecution>,
        <https://w3id.org/ontojourney/core#LearningJourneyExecution> .

<https://w3id.org/ontojourney/core#JourneyNarrative> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "JourneyNarrative"@en ;
    rdfs:comment "Narrative Content that organises the narrative progression of a Narrative Journey Model as a whole."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NarrativeContent> .

<https://w3id.org/ontojourney/core#Learner> a <http://purl.org/nemo/gufo#Role>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "Learner"@en ;
    rdfs:comment "A historical role instantiated by a Person through participation in a Learning Journey Execution."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#Person> .

<https://w3id.org/ontojourney/core#MissionSpecification> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "MissionSpecification"@en ;
    rdfs:comment "A Normative Description that states what the Learner is invited or expected to pursue within an HLJ stage and may combine a desired result with directions for action."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NormativeDescription> .

<https://w3id.org/ontojourney/core#NarrativeFraming> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "NarrativeFraming"@en ;
    rdfs:comment "Narrative Content that gives one HLJ Stage Specification its local narrative context and connects it to the wider journey."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NarrativeContent> .

<https://w3id.org/ontojourney/core#NarrativeJourneyExecution> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "NarrativeJourneyExecution"@en ;
    rdfs:comment "A Journey Execution of a Narrative Journey Model in which the performed stages enact a narratively organised journey."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#JourneyExecution> .

<https://w3id.org/ontojourney/core#Protagonist> a <http://purl.org/nemo/gufo#Role>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "Protagonist"@en ;
    rdfs:comment "A historical role instantiated by a Person through participation as the focal subject of a Heroic Narrative Journey Execution."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#Person> .

<https://w3id.org/ontojourney/core#AssistanceProvision> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "AssistanceProvision"@en ;
    rdfs:comment "An event within an HLJ Stage Execution in which assistance specified for that stage is provided."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#Event> .

<https://w3id.org/ontojourney/core#AssistanceSpecification> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "AssistanceSpecification"@en ;
    rdfs:comment "A Normative Description of support intended to be made available within an HLJ Stage Specification."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NormativeDescription> .

<https://w3id.org/ontojourney/core#ChallengeEncounter> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "ChallengeEncounter"@en ;
    rdfs:comment "An event within an HLJ Stage Execution in which the specified challenge of that stage is faced, whether or not it is successfully addressed."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#Event> .

<https://w3id.org/ontojourney/core#ChallengePerformance> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "ChallengePerformance"@en ;
    rdfs:comment "An event within an HLJ Stage Execution in which action is directed towards the specified challenge of that stage; its occurrence does not by itself imply success."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#Event> .

<https://w3id.org/ontojourney/core#ClosureSituation> a <http://purl.org/nemo/gufo#SituationType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "ClosureSituation"@en ;
    rdfs:comment "A situation brought about by a Journey Execution that satisfies a Closure Specification; in a successful execution, that specification is defined by the executed model."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#Situation> .

<https://w3id.org/ontojourney/core#ClosureSpecification> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "ClosureSpecification"@en ;
    rdfs:comment "A Condition Description defined by a Journey Model that states the condition under which an execution of the model counts as having reached closure."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#ConditionDescription> .

<https://w3id.org/ontojourney/core#GoalDescription> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "GoalDescription"@en ;
    rdfs:comment "A Normative Description whose propositional content describes a situation intended to be attained."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NormativeDescription> .

<https://w3id.org/ontojourney/core#HeroicNarrativeJourneyExecution> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "HeroicNarrativeJourneyExecution"@en ;
    rdfs:comment "A Narrative Journey Execution of a Heroic Narrative Journey Model that constitutes one focal heroic trajectory with exactly one Protagonist."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NarrativeJourneyExecution> .

<https://w3id.org/ontojourney/core#InformationObject> a <http://purl.org/nemo/gufo#Kind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "InformationObject"@en ;
    rdfs:comment "An entity whose identity is determined by its informational content and that may be expressed through different physical or digital carriers."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#FunctionalComplex> .

<https://w3id.org/ontojourney/core#LearningJourneyExecution> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "LearningJourneyExecution"@en ;
    rdfs:comment "A Journey Execution of a Learning Journey Model in which at least one Person participates as Learner."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#JourneyExecution> .

<https://w3id.org/ontojourney/core#LearningJourneyModel> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "LearningJourneyModel"@en ;
    rdfs:comment "A Journey Model and Plan Description that intentionally organises an educational experience and has at least one Educational Purpose."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#JourneyModel>,
        <https://w3id.org/ontojourney/core#PlanDescription> .

<https://w3id.org/ontojourney/core#NarrativeContent> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "NarrativeContent"@en ;
    rdfs:comment "An Information Object that organises characters, events, or themes as narrative content, independently of the medium through which it is expressed."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#InformationObject> .

<https://w3id.org/ontojourney/core#NarrativeJourneyModel> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "NarrativeJourneyModel"@en ;
    rdfs:comment "A Journey Model whose overall progression is organised by exactly one Journey Narrative."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#JourneyModel> .

<https://w3id.org/ontojourney/core#PlanDescription> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "PlanDescription"@en ;
    rdfs:comment "A Normative Description that prescribes or organises intended actions and events towards a purpose."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NormativeDescription> .

<https://w3id.org/ontojourney/core#TransformationEvent> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "TransformationEvent"@en ;
    rdfs:comment "An event within a Journey Execution that brings about one Realized Transformation."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#Event> .

<https://w3id.org/ontojourney/core#ChallengeSpecification> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "ChallengeSpecification"@en ;
    rdfs:comment "A Normative Description assigned to a Stage Specification that describes a demand, obstacle, problem, task, or condition that makes progression demanding."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#NormativeDescription> .

<https://w3id.org/ontojourney/core#Description> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "Description"@en ;
    rdfs:comment "An Information Object that expresses a conceptualization of entities or configurations and provides criteria for interpreting or assessing them."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#InformationObject> .

<https://w3id.org/ontojourney/core#HLJStageExecution> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "HLJStageExecution"@en ;
    rdfs:comment "A Stage Execution of an HLJ Stage Specification that may include Challenge Encounters, Challenge Performances, and Assistance Provisions connected to specifications of that same stage."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#StageExecution> .

<https://w3id.org/ontojourney/core#HLJStageSpecification> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "HLJStageSpecification"@en ;
    rdfs:comment "A Stage Specification and Plan Description in the Heroine's Learning Journey anatomy that contains exactly one Narrative Framing, Mission Specification, Challenge Specification, and Assistance Specification."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#PlanDescription>,
        <https://w3id.org/ontojourney/core#StageSpecification> .

<https://w3id.org/ontojourney/core#IntendedTransformation> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "IntendedTransformation"@en ;
    rdfs:comment "A Goal Description prescribed by a Journey Model that specifies a transformation the model is intended to bring about."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#GoalDescription> .

<https://w3id.org/ontojourney/core#Person> a <http://purl.org/nemo/gufo#Kind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "Person"@en ;
    rdfs:comment "A human individual who may participate in Journey Executions and whose identity is preserved across the historical roles Protagonist and Learner."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#FunctionalComplex> .

<https://w3id.org/ontojourney/core#RealizedTransformation> a <http://purl.org/nemo/gufo#SituationType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "RealizedTransformation"@en ;
    rdfs:comment "A situation brought about by one or more Transformation Events that represents an actual change concerning exactly one Person and satisfies one Intended Transformation."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#Situation> .

<https://w3id.org/ontojourney/core#StageExecution> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "StageExecution"@en ;
    rdfs:comment "An event within a Journey Execution that enacts one Stage Specification belonging to the executed Journey Model."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#Event> .

<https://w3id.org/ontojourney/core#JourneyExecution> a <http://purl.org/nemo/gufo#EventType>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "JourneyExecution"@en ;
    rdfs:comment "A complex event in which one Journey Model is enacted in a particular context through one or more Stage Executions."@en ;
    rdfs:subClassOf <http://purl.org/nemo/gufo#Event> .

<https://w3id.org/ontojourney/core#JourneyModel> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "JourneyModel"@en ;
    rdfs:comment "A Description that characterises a reusable journey pattern through one or more Stage Specifications and one Closure Specification, and may prescribe Intended Transformations."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#Description> .

<https://w3id.org/ontojourney/core#NormativeDescription> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "NormativeDescription"@en ;
    rdfs:comment "A Description that prescribes, permits, or evaluates possible actions or situations instead of merely characterising them."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#Description> .

<https://w3id.org/ontojourney/core#StageSpecification> a <http://purl.org/nemo/gufo#SubKind>,
        owl:Class,
        owl:NamedIndividual ;
    rdfs:label "StageSpecification"@en ;
    rdfs:comment "A Description that characterises a model-specific stage of a Journey Model, whether as a descriptive pattern or as a prescribed part of a plan, and may be linked to other Stage Specifications through directlyPrecedesStage."@en ;
    rdfs:subClassOf <https://w3id.org/ontojourney/core#Description> .

